const serviceLinks = {
    "Development & Design": [
      { href: '/web-development', label: 'Web Development', icon: <Code className="w-5 h-5"/> },
      { href: '/mobile-development', label: 'Mobile Development', icon: <Smartphone className="w-5 h-5"/> },
      { href: '/software-development', label: 'Software Development', icon: <PenSquare className="w-5 h-5"/> },
      { href: '/graphic-design', label: 'Graphic Design', icon: <Palette className="w-5 h-5"/> },
      { href: '/ui-ux-development', label: 'UI/UX Development', icon: <AppWindow className="w-5 h-5"/> },
    ],
    "Marketing & Strategy": [
      { href: '/search-engine-optimization', label: 'SEO', icon: <Search className="w-5 h-5"/> },
      { href: '/social-media-marketing', label: 'Social Media Marketing', icon: <Megaphone className="w-5 h-5"/> },
      { href: '/pay-per-click-advertising', label: 'PPC Advertising', icon: <Target className="w-5 h-5"/> },
      { href: '/content-marketing', label: 'Content Marketing', icon: <MessageCircle className="w-5 h-5"/> },
    ]
};


const navLinks = [
  { href: '/', label: 'Home' },
  { 
    label: 'Services', 
    href: '/services',
  },
  { 
    label: 'About Us',
    href: '/about',
  },
  { href: '/portfolio', label: 'Project' },
  { 
    label: 'Clients',
    href: '#', 
  },
  { href: '/blog', label: 'Blog' },
];

export default function Header() {
  const pathname = usePathname();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
  }, []);
  
  if (!isMounted) {
    return null;
  }

  const NavLink = ({ href, children, className }: { href: string; children: React.ReactNode, className?: string }) => {
    const isActive = pathname === href;
    return (
        <SheetClose asChild>
            <Link
                href={href}
                className={cn(
                    'block py-2 text-sm font-normal relative bg-clip-text text-transparent bg-gradient-to-r from-black to-black',
                    'hover:from-accent hover:to-primary-foreground hover:bg-clip-text hover:animate-shimmer hover:bg-[length:200%_100%]',
                    isActive ? 'text-accent' : 'text-black',
                    className
                )}
            >
                {children}
            </Link>
        </SheetClose>
    );
  };
  
  const CollapsibleNavLink = ({ href, children }: { href: string; children: React.ReactNode }) => {
    const isActive = pathname === href;
    return (
        <SheetClose asChild>
            <Link
                href={href}
                className={cn(
                    'block py-2 text-sm font-normal relative bg-clip-text text-transparent bg-gradient-to-r from-black to-black',
                    'hover:from-accent hover:to-primary-foreground hover:bg-clip-text hover:animate-shimmer hover:bg-[length:200%_100%]',
                    isActive ? 'text-accent' : 'text-black'
                )}
            >
                {children}
            </Link>
        </SheetClose>
    );
};


  return (
    <header className="sticky top-0 z-50 w-full border-b bg-primary">
      <div className="container mx-auto flex h-16 items-center justify-between px-4 sm:px-6 lg:px-8">
        <Link href="/" className="flex items-center space-x-2">
          <SulzaXLogo />
        </Link>
        
        <nav className="hidden md:flex items-center space-x-6 lg:space-x-8">
            {navLinks.map((link) => {
              if (link.label === 'Services') {
                return (
                  <div key={link.label} className="group relative">
                     <Link
                        href={link.href || '#'}
                        className={cn(
                        'relative transition-colors text-sm font-medium text-primary-foreground group flex items-center gap-1',
                        pathname.startsWith('/services') ? 'text-accent-foreground' : 'hover:text-primary-foreground/80'
                        )}
                    >
                        {link.label}
                        <ChevronDown className="h-4 w-4 transition-transform duration-300 group-hover:rotate-180" />
                    </Link>
                    <div className="absolute top-full left-1/2 -translate-x-1/2 mt-2 w-screen max-w-4xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-300">
                        <div className="bg-white rounded-lg shadow-xl p-8 grid grid-cols-2 gap-8">
                           {Object.entries(serviceLinks).map(([category, links]) => (
                                <div key={category}>
                                    <h3 className="font-bold text-black mb-4">{category}</h3>
                                    <ul className="space-y-3">
                                        {links.map((subLink, index) => (
                                            <li key={subLink.href} className="opacity-0 animate-fade-slide-up" style={{ animationDelay: `${index * 50}ms` }}>
                                                <Link href={subLink.href} className="flex items-center gap-3 text-sm text-gray-600 hover:text-accent group/item">
                                                   <div className="p-2 bg-secondary rounded-full group-hover/item:bg-accent/20 transition-colors">
                                                     {React.cloneElement(subLink.icon, { className: 'w-4 h-4 text-accent' })}
                                                   </div>
                                                   <span>{subLink.label}</span>
                                                </Link>
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                           ))}
                        </div>
                    </div>
                  </div>
                )
              }
              
              return (
                 <Link
                    key={link.label}
                    href={link.href || '#'}
                    className={cn(
                    'relative transition-colors text-sm font-medium text-primary-foreground group',
                    pathname === link.href ? 'text-accent-foreground' : 'hover:text-primary-foreground/80'
                    )}
                >
                    {link.label}
                    <span className={cn(
                    'absolute -bottom-1 left-0 w-0 h-0.5 bg-accent transition-all duration-300 group-hover:w-full',
                        pathname === link.href ? 'w-full' : ''
                    )}></span>
                </Link>
              )
            })}
        </nav>
        
        <div className="flex items-center gap-4">
          <div className="md:hidden">
            <Sheet open={isMobileMenuOpen} onOpenChange={setIsMobileMenuOpen}>
              <SheetTrigger asChild>
                <Button variant="ghost" size="icon" className="text-primary-foreground hover:bg-transparent focus-visible:ring-0 focus-visible:ring-offset-0">
                  <Menu className="h-6 w-6" />
                  <span className="sr-only">Toggle Menu</span>
                </Button>
              </SheetTrigger>
              <SheetContent side="right" className="bg-white p-0 w-[80vw] sm:w-[350px]">
                <SheetHeader className="flex flex-row items-center justify-between p-4">
                   <SheetTitle className="sr-only">Mobile Menu</SheetTitle>
                    <SheetClose asChild>
                        <Button variant="ghost" size="icon" className="text-black hover:bg-transparent focus-visible:ring-0 focus-visible:ring-offset-0">
                            <X className="h-5 w-5" />
                            <span className="sr-only">Close</span>
                        </Button>
                    </SheetClose>
                </SheetHeader>
                <ScrollArea className="flex-grow px-6">
                    <div className="grid gap-2 py-6">
                        {navLinks.map((link) => {
                             if (link.label === 'Services') {
                                const allServiceLinks = Object.values(serviceLinks).flat();
                                return (
                                    <Collapsible key={link.label}>
                                        <CollapsibleTrigger className="flex w-full items-center justify-between gap-1 py-2 text-sm text-black group">
                                            <span>{link.label}</span>
                                            <ChevronDown className="h-4 w-4 transition-transform duration-300 group-data-[state=open]:rotate-180" />
                                        </CollapsibleTrigger>
                                        <CollapsibleContent>
                                            <div className="grid gap-1 pl-4 pt-2">
                                                {allServiceLinks.map(subLink => (
                                                    <CollapsibleNavLink key={subLink.href} href={subLink.href}>
                                                        {subLink.label}
                                                    </CollapsibleNavLink>
                                                ))}
                                            </div>
                                        </CollapsibleContent>
                                    </Collapsible>
                                )
                             }
                            
                            return (
                                <NavLink key={link.href} href={link.href!} className="text-black">
                                    {link.label}
                                </NavLink>
                            )
                        })}
                    </div>
                </ScrollArea>
                <div className="p-6">
                    <SheetClose asChild>
                        <Button asChild className="w-full font-semibold bg-accent hover:bg-accent/90 text-accent-foreground">
                            <Link href="/contact">Contact</Link>
                        </Button>
                    </SheetClose>
                </div>
              </SheetContent>
            </Sheet>
          </div>
          
          <div className="hidden md:flex items-center space-x-4">
            <a href="tel:+12013740018" className="flex items-center gap-2 text-sm font-medium text-primary-foreground hover:text-primary-foreground/80">
                <Phone className="w-5 h-5 text-accent" />
                <span>+1(201) 374-0018</span>
            </a>
            <Button asChild className="font-semibold bg-accent hover:bg-accent/90 text-accent-foreground rounded-md px-6">
              <Link href="/contact">Contact</Link>
            </Button>
            </div>
        </div>
      </div>
    </header>
  );
}
